package com.bananalab.lite;
import android.content.*;
import org.json.*;import java.util.*;import java.util.regex.*;
/** Two saved sources that define the same term with different figures, or with almost no words in common.
 *  It only points at the pair; which one is right is the user's call. */
final class SourceConflicts{
 static final int MAX=40;
 static SharedPreferences prefs(Context c){return c.getSharedPreferences("banana-source-conflicts",0);}
 static final class Pair{final String term,first,second,firstSource,secondSource,why;Pair(String t,String a,String b,String sa,String sb,String w){term=t;first=a;second=b;firstSource=sa;secondSource=sb;why=w;}}
 static Set<String> figures(String sentence){Set<String> out=new TreeSet<>();Matcher m=Pattern.compile("[0-9]+(?:[.,][0-9]+)*").matcher(sentence);while(m.find())out.add(m.group().replaceAll("[.,]",""));return out;}
 /** "figures" when both give numbers and share none; "wording" when the definitions share under a fifth of their words; else null. */
 static String differ(String a,String b){Set<String> fa=figures(a),fb=figures(b);if(!fa.isEmpty()&&!fb.isEmpty()){for(String f:fa)if(fb.contains(f))return null;return "figures";}Set<String> wa=ReadingKnowledge.words(a),wb=ReadingKnowledge.words(b);if(wa.size()<3||wb.size()<3)return null;int common=ReadingKnowledge.common(wa,wb);Set<String> all=new HashSet<>(wa);all.addAll(wb);return common/(double)all.size()<.2?"wording":null;}
 static List<Pair> find(JSONArray rows)throws Exception{Map<String,List<ReadingKnowledge.Definition>> by=new LinkedHashMap<>();for(ReadingKnowledge.Definition d:ReadingKnowledge.definitions(rows)){String key=ChatLanguage.normalize(d.term).replaceFirst("^(?:el|la|los|las|un|una) ","");if(key.length()<3)continue;List<ReadingKnowledge.Definition> list=by.get(key);if(list==null)by.put(key,list=new ArrayList<>());list.add(d);}
  List<Pair> out=new ArrayList<>();for(Map.Entry<String,List<ReadingKnowledge.Definition>> e:by.entrySet()){List<ReadingKnowledge.Definition> list=e.getValue();outer:for(int i=0;i<list.size();i++)for(int j=i+1;j<list.size();j++){ReadingKnowledge.Definition a=list.get(i),b=list.get(j);if(a.row.getString("id").equals(b.row.getString("id")))continue;String body=a.sentence.replaceFirst("(?iu)^.*? (?:es|son|significa|se define como|consiste en) ",""),other=b.sentence.replaceFirst("(?iu)^.*? (?:es|son|significa|se define como|consiste en) ","");String why=differ(body,other);if(why!=null){out.add(new Pair(a.term,a.sentence,b.sentence,ReadingKnowledge.source(a.row),ReadingKnowledge.source(b.row),why));if(out.size()>=MAX)return out;break outer;}}}return out;}
 static String describe(List<Pair> pairs,int documents){if(pairs.isEmpty())return "No encontré definiciones enfrentadas en "+documents+" documentos revisados. Sólo comparo oraciones del tipo «X es…» sobre el mismo término: dos fuentes pueden contradecirse de otras formas que no detecto.";StringBuilder out=new StringBuilder("Encontré "+pairs.size()+(pairs.size()==1?" término":" términos")+" con definiciones que no coinciden entre fuentes:\n");for(int i=0;i<Math.min(6,pairs.size());i++){Pair p=pairs.get(i);out.append("\n").append(i+1).append(". ").append(p.term).append(p.why.equals("figures")?" — dan cifras distintas":" — lo describen de forma muy distinta").append("\n«").append(p.first).append("»\nFuente: ").append(p.firstSource).append("\n«").append(p.second).append("»\nFuente: ").append(p.secondSource).append('\n');}if(pairs.size()>6)out.append("\n…y ").append(pairs.size()-6).append(" más.\n");return out.append("\nNo sé cuál es correcta. Si lo sabés, decime «Te corrijo: …» con el dato y tu corrección tendrá prioridad. Mientras tanto no estudio esas definiciones.").toString();}
 /** Scans a sample of the library, remembers the conflicting terms and returns the report. */
 static String report(Context c)throws Exception{NotebookDisk disk=NotebookDisk.of(c);JSONArray rows=NotebookDisk.rows(disk.index.sample(600),200,4);List<Pair> pairs=find(rows);JSONArray terms=new JSONArray();for(Pair p:pairs)terms.put(ChatLanguage.normalize(p.term));prefs(c).edit().putString("terms",terms.toString()).putLong("time",System.currentTimeMillis()).apply();return describe(pairs,rows.length());}
 /** Terms whose definitions are in dispute: the reader does not study them until the user settles it. */
 static Set<String> disputed(Context c){Set<String> out=new HashSet<>();try{JSONArray terms=new JSONArray(prefs(c).getString("terms","[]"));for(int i=0;i<terms.length();i++)out.add(terms.getString(i));}catch(Exception ignored){}return out;}
}
